css:
.pp-stage { border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; }
.pp-stage canvas { touch-action: none; cursor: grab; }
.pp-stage canvas.holding { cursor: grabbing; }
.pp-count { margin: 0; display: flex; flex-wrap: wrap; gap: 8px 16px; font-size: 20px; }
.pp-count b { font-size: 26px; color: var(--accent); }
.pp-count .pp-name { flex-basis: 100%; font-weight: 800; }
.pp-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 3.2em; }

js:
/* tongsci1.2-2-1.2.peptide */
(function () {
  'use strict';
  const { part } = window.Deck;
  const single = (btns) => btns.forEach((b) => b.addEventListener('click', () => {
    const on = b.getAttribute('aria-pressed') !== 'true';
    btns.forEach((x) => x.setAttribute('aria-pressed', String(on && x === b)));
  }));
  part('tongsci1-2-2-1-2-peptide', (root) => window.Peptide.mount(root));
})();
